export async function fetchWithSafeRetry(
  url: string,
  options: RequestInit,
  maxRetries = 3
): Promise<Response> {
  const method = (options.method || "GET").toUpperCase();
  const isIdempotent = ["GET", "HEAD", "PUT", "DELETE"].includes(method);

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      const res = await fetch(url, options);
      // Only retry on transient upstream gateway errors
      if ([502, 503, 504].includes(res.status) && isIdempotent) {
        if (attempt === maxRetries) return res;
        await new Promise((r) => setTimeout(r, Math.pow(2, attempt) * 100));
        continue;
      }
      return res;
    } catch (err) {
      // Never blindly retry failed POST requests without idempotency keys
      if (!isIdempotent) throw err;
      if (attempt === maxRetries) throw err;
      await new Promise((r) => setTimeout(r, Math.pow(2, attempt) * 100));
    }
  }
  throw new Error("Retry loop exhausted");
}

type ProtocolRequirement = "STRICT_ORDERING" | "LOW_LATENCY_UNBOUNDED" | "STREAMING_AUDIO_VIDEO";

export function selectTransportProtocol(req: ProtocolRequirement): "TCP" | "UDP" {
  switch (req) {
    case "STRICT_ORDERING":
      // Financial transactions, REST APIs, database queries, file transfers
      return "TCP";
    case "LOW_LATENCY_UNBOUNDED":
      // DNS queries, NTP time sync, multiplayer game player coordinates
      return "UDP";
    case "STREAMING_AUDIO_VIDEO":
      // Live WebRTC calls where an old dropped video frame is useless
      return "UDP";
  }
}

import https from 'node:https';
import fs from 'node:fs';

const server = https.createServer({
  key: fs.readFileSync('/etc/ssl/certs/privkey.pem'),
  cert: fs.readFileSync('/etc/ssl/certs/fullchain.pem'),
  // Enforce TLS 1.3 minimum to eliminate legacy insecure ciphers
  minVersion: 'TLSv1.3',
  ciphers: [
    'TLS_AES_256_GCM_SHA384',
    'TLS_CHACHA20_POLY1305_SHA256',
    'TLS_AES_128_GCM_SHA256'
  ].join(':'),
  honorCipherOrder: true,
});

import { WebSocketServer, WebSocket } from 'ws';
import { createClient } from 'redis';

const wss = new WebSocketServer({ port: 8080 });
const redisSub = createClient();
const activeClients = new Map<string, WebSocket>();

wss.on('connection', (ws, req) => {
  const userId = new URL(req.url!, 'http://localhost').searchParams.get('userId');
  if (userId) activeClients.set(userId, ws);

  ws.on('close', () => {
    if (userId) activeClients.delete(userId);
  });
});

// Cross-node distribution via Redis Pub/Sub
await redisSub.subscribe('user-messages', (messageStr) => {
  const { targetUserId, payload } = JSON.parse(messageStr);
  const clientWs = activeClients.get(targetUserId);
  if (clientWs && clientWs.readyState === WebSocket.OPEN) {
    clientWs.send(JSON.stringify(payload));
  }
});

syntax = "proto3";
package orders.v1;

service OrderService {
  rpc CreateOrder (CreateOrderRequest) returns (CreateOrderResponse);
  rpc StreamOrderStatus (OrderStatusRequest) returns (stream OrderStatusUpdate);
}

message CreateOrderRequest {
  string user_id = 1;
  repeated OrderItem items = 2;
  double total_amount = 3;
}

message OrderItem {
  string product_id = 1;
  int32 quantity = 2;
  double unit_price = 3;
}

message CreateOrderResponse {
  string order_id = 1;
  string status = 2;
  int64 created_at_unix = 3;
}

/*
 * HikariCP PostgreSQL Connection Pool Formula:
 * Pool Size = (Core Count * 2) + Effective Spindle Count (Disk Channels)
 *
 * For a 16-vCPU database instance backed by fast SSD:
 * Optimal Connections = (16 * 2) + 1 = 33 connections!
 */

import { Pool } from 'pg';

export const dbPool = new Pool({
  host: process.env.DB_HOST,
  database: 'production_orders',
  max: 30, // Bounded pool per container to prevent DB exhaustion
  min: 5,  // Maintain warm idle connections
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000, // Fail fast if pool is starved
});
